import { Link } from '@tanstack/react-router'
import type { Fund, PortfolioCompany } from '../lib/organizations'

type DashboardProps = { fund: Fund; portco?: PortfolioCompany }

export function Dashboard({ fund, portco }: DashboardProps) {
  const scopeName = portco?.name ?? fund.name
  const scopeDescription = portco?.focus ?? 'A shared view of portfolio leadership decisions and their evidence.'

  return <main className="app-shell"><aside className="scope-rail"><Link to="/" className="wordmark">Second Brain</Link><nav aria-label="Fund navigation" className="scope-nav"><Link to="/fund/$fundSlug" params={{ fundSlug: fund.slug }} activeOptions={{ exact: true }}>Fund overview</Link><Link to="/fund/$fundSlug/portco" params={{ fundSlug: fund.slug }} activeOptions={{ exact: true }}>Portfolio companies</Link></nav><p className="scope-caption">{fund.description}</p></aside><div className="reading-pane"><header className="page-heading"><p className="breadcrumb"><Link to="/fund/$fundSlug" params={{ fundSlug: fund.slug }}>{fund.name}</Link>{portco ? ` / ${portco.code}` : ''}</p><h1>{scopeName}</h1><p>{scopeDescription}</p></header><section className="agenda" aria-labelledby="agenda-heading"><div><h2 id="agenda-heading">Leadership agenda</h2><p>{portco ? 'The current issue that requires a decision.' : 'The portfolio issues that merit attention this week.'}</p></div><p className={portco ? `status status-${portco.status.replaceAll(' ', '-')}` : 'status'}>{portco?.status ?? `${fund.portcos.length} active companies`}</p></section>{portco ? <PortcoDetails portco={portco} /> : <PortfolioTable fund={fund} />}</div></main>
}

function PortfolioTable({ fund }: { fund: Fund }) {
  return <section className="data-section" aria-labelledby="portfolio-heading"><div className="section-heading"><h2 id="portfolio-heading">Portfolio</h2><Link to="/fund/$fundSlug/portco" params={{ fundSlug: fund.slug }}>View all companies</Link></div><div className="company-list">{fund.portcos.map((portco) => <Link key={portco.slug} to="/fund/$fundSlug/portco/$portcoSlug" params={{ fundSlug: fund.slug, portcoSlug: portco.slug }} className="company-row"><span className="company-code">{portco.code}</span><span><strong>{portco.name}</strong><small>{portco.sector}</small></span><span className={`status status-${portco.status.replaceAll(' ', '-')}`}>{portco.status}</span></Link>)}</div></section>
}

function PortcoDetails({ portco }: { portco: PortfolioCompany }) {
  return <section className="data-section" aria-labelledby="context-heading"><div className="section-heading"><h2 id="context-heading">Scope</h2></div><dl className="detail-list"><div><dt>Sector</dt><dd>{portco.sector}</dd></div><div><dt>Location</dt><dd>{portco.location}</dd></div><div><dt>Current focus</dt><dd>{portco.focus}</dd></div></dl></section>
}

export type PortfolioCompany = {
  slug: string
  code: string
  name: string
  sector: string
  location: string
  status: 'on pace' | 'needs attention' | 'on plan'
  focus: string
}

export type Fund = {
  slug: string
  name: string
  description: string
  portcos: PortfolioCompany[]
}

export const funds: Fund[] = [
  {
    slug: 'daw-capital',
    name: 'DAW Capital',
    description: 'Lower-middle-market private equity',
    portcos: [
      { slug: 'vantage-managed-services', code: 'PC1', name: 'Vantage Managed Services', sector: 'IT / managed services', location: 'Denver, CO', status: 'on pace', focus: 'Retain the CTO and build the finance bench.' },
      { slug: 'cascade-care-group', code: 'PC2', name: 'Cascade Care Group', sector: 'Healthcare provider services', location: 'Portland, OR', status: 'needs attention', focus: 'Stabilize leadership around COO retention and the finance bench.' },
      { slug: 'ridgeline-freight-logistics', code: 'PC3', name: 'Ridgeline Freight & Logistics', sector: 'Transportation & logistics', location: 'Salt Lake City, UT', status: 'on plan', focus: 'Execute the founder-CEO succession and backfill the COO.' },
    ],
  },
]

export function getFund(slug: string) {
  return funds.find((fund) => fund.slug === slug)
}

export function getPortco(fundSlug: string, portcoSlug: string) {
  return getFund(fundSlug)?.portcos.find((portco) => portco.slug === portcoSlug)
}

