import { Link, createFileRoute } from '@tanstack/react-router'
import { funds } from '../lib/organizations'

export const Route = createFileRoute('/')({ component: Home })

function Home() {
  return (
    <main className="fund-index">
      <header className="index-heading">
        <p className="wordmark">Second Brain</p>
        <h1>Workspaces</h1>
        <p>Choose a fund to review its people record, portfolio context, and active decisions.</p>
      </header>
      <section className="fund-list" aria-label="Available funds">
        {funds.map((fund) => (
          <Link
            key={fund.slug}
            to="/fund/$fundSlug"
            params={{ fundSlug: fund.slug }}
            className="fund-row"
          >
            <span>
              <strong>{fund.name}</strong>
              <small>{fund.description}</small>
            </span>
            <span>{fund.portcos.length} portfolio companies</span>
          </Link>
        ))}
      </section>
    </main>
  )
}

