    if (input.portcoId) {
      const [portco] = await db
        .select({ id: portcos.id })
        .from(portcos)
        .where(and(eq(portcos.id, input.portcoId), eq(portcos.fundId, input.fundId)));
      if (!portco) throw new DocumentModuleError('Portco not found for fund', 404);
    }

