import { useQuery } from '@tanstack/react-query'
import { Link, notFound } from '@tanstack/react-router'
import { fetchFunds, fetchPortcos } from '../../lib/fund-queries'
import { getFund, getPortco } from '../../lib/organizations'

type ScopeReference = { id: string; slug?: never } | { slug: string; id?: never }

export type DashboardScope = {
  fund: ScopeReference
  portco?: ScopeReference
}

type DashboardProps = { scope: DashboardScope }

/**
 * The dashboard module has one interface: a fund scope plus an optional
 * portco scope. Its callers do not choose a dashboard variant or resolve data.
 */
export default function Dashboard({ scope }: DashboardProps) {
  const funds = useQuery({ queryKey: ['funds'], queryFn: fetchFunds })
  const apiFund = findReference(funds.data?.data, scope.fund)
  const portcos = useQuery({
    queryKey: ['funds', apiFund?.id, 'portcos'],
    queryFn: () => fetchPortcos(apiFund!.id),
    enabled: Boolean(apiFund && scope.portco),
  })

  if (funds.isError) return <DashboardState>{funds.error.message}</DashboardState>
  if (funds.isPending) return <DashboardState>Loading dashboard…</DashboardState>
  if (scope.portco && portcos.isError)
    return <DashboardState>{portcos.error.message}</DashboardState>
  if (scope.portco && portcos.isPending) return <DashboardState>Loading dashboard…</DashboardState>

  if (!apiFund) throw notFound()
  const fund = getFund(apiFund.slug)
  if (!fund) throw notFound()

  const apiPortco = scope.portco ? findReference(portcos.data?.data, scope.portco) : undefined
  const portco = apiPortco ? getPortco(fund.slug, apiPortco.slug) : undefined
  if (scope.portco && !portco) throw notFound()

  const scopeName = portco?.name ?? fund.name
  const scopeDescription =
    portco?.focus ?? 'A shared view of portfolio leadership decisions and their evidence.'

  return (
    <main className="app-shell">
      <aside className="scope-rail">
        <Link to="/" className="wordmark">
          Second Brain
        </Link>
        <nav aria-label="Fund navigation" className="scope-nav">
          <Link
            to="/fund/$fundSlug"
            params={{ fundSlug: fund.slug }}
            activeOptions={{ exact: true }}
          >
            Fund overview
          </Link>
          <Link
            to="/fund/$fundSlug/portco"
            params={{ fundSlug: fund.slug }}
            activeOptions={{ exact: true }}
          >
            Portfolio companies
