import { Hono } from 'hono';
import { cors } from 'hono/cors';
import { asc, eq } from 'drizzle-orm';
import { db } from './db/client.js';
import { funds, portcos } from './db/schema.js';

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const isUuid = (value: string) => uuidPattern.test(value);

export const app = new Hono()
  .use(
    '*',
    cors({
      origin: 'http://localhost:3000',
    }),
  )
  .get('/health', (c) => c.json({ status: 'ok' }))
  .get('/funds', async (c) => {
    const rows = await db
      .select({ id: funds.id, name: funds.name, slug: funds.slug })
      .from(funds)
      .orderBy(asc(funds.name), asc(funds.id));

    return c.json({ data: rows });
  })
  .get('/funds/:fundId/portcos', async (c) => {
    const fundId = c.req.param('fundId');
    if (!isUuid(fundId)) {
      return c.json({ error: 'Invalid fund id' }, 400);
    }

    const [fund] = await db.select({ id: funds.id }).from(funds).where(eq(funds.id, fundId));
    if (!fund) {
      return c.json({ error: 'Fund not found' }, 404);
    }

    const rows = await db
      .select({
        id: portcos.id,
        fundId: portcos.fundId,
        code: portcos.code,
        name: portcos.name,
        slug: portcos.slug,
      })
      .from(portcos)
      .where(eq(portcos.fundId, fundId))
      .orderBy(asc(portcos.code), asc(portcos.id));

    return c.json({ data: rows });
  })
  .get('/dump', (c) =>
    c.json({
      message: 'Frontend-to-backend RPC is working.',
      service: 'second-brain-api',
      checkedAt: new Date().toISOString(),
    }),
  )
  .notFound((c) => c.json({ error: 'Not found' }, 404))
  .onError((error, c) => {
    console.error(error);
    return c.json({ error: 'Internal server error' }, 500);
  });

export type AppType = typeof app;
export type PortfolioCompany = {
  slug: string
  code: string
  name: string
  sector: string
  location: string
  status: 'on pace' | 'needs attention' | 'on plan'
  focus: string
}

export type Fund = {
  slug: string
  name: string
  description: string
  portcos: PortfolioCompany[]
}

export const funds: Fund[] = [
  {
    slug: 'daw-capital',
    name: 'DAW Capital',
    description: 'Lower-middle-market private equity',
    portcos: [
      {
        slug: 'vantage-managed-services',
        code: 'PC1',
        name: 'Vantage Managed Services',
        sector: 'IT / managed services',
        location: 'Denver, CO',
        status: 'on pace',
        focus: 'Retain the CTO and build the finance bench.',
      },
      {
        slug: 'cascade-care-group',
        code: 'PC2',
        name: 'Cascade Care Group',
        sector: 'Healthcare provider services',
        location: 'Portland, OR',
        status: 'needs attention',
        focus: 'Stabilize leadership around COO retention and the finance bench.',
      },
      {
        slug: 'ridgeline-freight-logistics',
        code: 'PC3',
        name: 'Ridgeline Freight & Logistics',
        sector: 'Transportation & logistics',
        location: 'Salt Lake City, UT',
        status: 'on plan',
        focus: 'Execute the founder-CEO succession and backfill the COO.',
      },
    ],
  },
]

export function getFund(slug: string) {
  return funds.find((fund) => fund.slug === slug)
}

export function getPortco(fundSlug: string, portcoSlug: string) {
  return getFund(fundSlug)?.portcos.find((portco) => portco.slug === portcoSlug)
}
import { Link, createFileRoute } from '@tanstack/react-router'
import { funds } from '../lib/organizations'

export const Route = createFileRoute('/')({ component: Home })

function Home() {
  return (
    <main className="fund-index">
      <header className="index-heading">
        <p className="wordmark">Second Brain</p>
        <h1>Workspaces</h1>
        <p>Choose a fund to review its people record, portfolio context, and active decisions.</p>
      </header>
      <section className="fund-list" aria-label="Available funds">
        {funds.map((fund) => (
          <Link
            key={fund.slug}
            to="/fund/$fundSlug"
            params={{ fundSlug: fund.slug }}
            className="fund-row"
          >
            <span>
              <strong>{fund.name}</strong>
              <small>{fund.description}</small>
            </span>
            <span>{fund.portcos.length} portfolio companies</span>
          </Link>
        ))}
      </section>
    </main>
  )
}
import { Link, createFileRoute, notFound } from '@tanstack/react-router'
import { getFund } from '../../../../lib/organizations'

export const Route = createFileRoute('/fund/$fundSlug/portco/')({ component: PortcoList })

function PortcoList() {
  const { fundSlug } = Route.useParams()
  const fund = getFund(fundSlug)

  if (!fund) throw notFound()

  return (
    <main className="fund-index">
      <header className="index-heading">
        <p className="breadcrumb">
          <Link to="/fund/$fundSlug" params={{ fundSlug: fund.slug }}>
            {fund.name}
          </Link>
        </p>
        <h1>Portfolio companies</h1>
        <p>Choose a company to work within its scoped record.</p>
      </header>
      <section className="fund-list" aria-label={`${fund.name} portfolio companies`}>
        {fund.portcos.map((portco) => (
          <Link
            key={portco.slug}
            to="/fund/$fundSlug/portco/$portcoSlug"
            params={{ fundSlug: fund.slug, portcoSlug: portco.slug }}
            className="fund-row"
          >
            <span>
              <strong>{portco.name}</strong>
              <small>{portco.sector}</small>
            </span>
            <span className={`status status-${portco.status.replaceAll(' ', '-')}`}>
              {portco.status}
            </span>
          </Link>
        ))}
      </section>
    </main>
  )
}
import { hc } from 'hono/client'
import type { AppType } from '@second-brain/api'

const apiUrl = import.meta.env.VITE_API_URL ?? 'http://localhost:8787'

export const api = hc<AppType>(apiUrl)
