import { Link, notFound } from '@tanstack/react-router'
import { getFund, getPortco } from '../../lib/organizations'

type ScopeReference = { id: string; slug?: never } | { slug: string; id?: never }

export type DashboardScope = {
  fund: ScopeReference
  portco?: ScopeReference
}

type DashboardProps = { scope: DashboardScope }

/**
 * The dashboard module has one interface: a fund scope plus an optional
 * portco scope. Its callers do not choose a dashboard variant or resolve data.
 */
export default function Dashboard({ scope }: DashboardProps) {
  const { fund, portco } = resolveScope(scope)
  const scopeName = portco?.name ?? fund.name
  const scopeDescription =
    portco?.focus ?? 'A shared view of portfolio leadership decisions and their evidence.'

  return (
    <main className="app-shell">
      <aside className="scope-rail">
        <Link to="/" className="wordmark">
          Second Brain
        </Link>
        <nav aria-label="Fund navigation" className="scope-nav">
          <Link
            to="/fund/$fundSlug"
            params={{ fundSlug: fund.slug }}
            activeOptions={{ exact: true }}
          >
            Fund overview
          </Link>
          <Link
            to="/fund/$fundSlug/portco"
            params={{ fundSlug: fund.slug }}
            activeOptions={{ exact: true }}
          >
            Portfolio companies
          </Link>
        </nav>
        <p className="scope-caption">{fund.description}</p>
      </aside>
      <div className="reading-pane">
        <header className="page-heading">
          <p className="breadcrumb">
            <Link to="/fund/$fundSlug" params={{ fundSlug: fund.slug }}>
              {fund.name}
            </Link>
            {portco ? ` / ${portco.code}` : ''}
          </p>
          <h1>{scopeName}</h1>
          <p>{scopeDescription}</p>
        </header>
        <section className="agenda" aria-labelledby="agenda-heading">
          <div>
            <h2 id="agenda-heading">Leadership agenda</h2>
            <p>
              {portco
                ? 'The current issue that requires a decision.'
                : 'The portfolio issues that merit attention this week.'}
            </p>
          </div>
          <p className={portco ? `status status-${portco.status.replaceAll(' ', '-')}` : 'status'}>
            {portco?.status ?? `${fund.portcos.length} active companies`}
          </p>
        </section>
        {portco ? (
          <PortcoDetails portco={portco} />
        ) : (
          <PortfolioTable fundSlug={fund.slug} portcos={fund.portcos} />
        )}
      </div>
    </main>
  )
}

function resolveScope(scope: DashboardScope) {
  // The current adapter resolves slugs from the local seed model. IDs are part
  // of the module interface now so the forthcoming persisted adapter can use
  // the same caller contract without changing any routes.
  if (!('slug' in scope.fund)) throw notFound()
  const fund = getFund(scope.fund.slug)
  if (!fund) throw notFound()

  if (!scope.portco) return { fund }
  if (!('slug' in scope.portco)) throw notFound()
  const portco = getPortco(fund.slug, scope.portco.slug)
  if (!portco) throw notFound()

  return { fund, portco }
}

function PortfolioTable({
  fundSlug,
  portcos,
}: {
  fundSlug: string
  portcos: ReturnType<typeof getFund>['portcos']
}) {
  return (
    <section className="data-section" aria-labelledby="portfolio-heading">
      <div className="section-heading">
        <h2 id="portfolio-heading">Portfolio</h2>
        <Link to="/fund/$fundSlug/portco" params={{ fundSlug }}>
          View all companies
        </Link>
      </div>
      <div className="company-list">
        {portcos.map((portco) => (
          <Link
            key={portco.slug}
            to="/fund/$fundSlug/portco/$portcoSlug"
            params={{ fundSlug, portcoSlug: portco.slug }}
            className="company-row"
          >
            <span className="company-code">{portco.code}</span>
            <span>
              <strong>{portco.name}</strong>
              <small>{portco.sector}</small>
            </span>
            <span className={`status status-${portco.status.replaceAll(' ', '-')}`}>
              {portco.status}
            </span>
          </Link>
        ))}
      </div>
    </section>
  )
}

function PortcoDetails({ portco }: { portco: NonNullable<ReturnType<typeof getPortco>> }) {
  return (
    <section className="data-section" aria-labelledby="context-heading">
      <div className="section-heading">
        <h2 id="context-heading">Scope</h2>
      </div>
      <dl className="detail-list">
