import { Hono } from 'hono';
import { cors } from 'hono/cors';
import { asc, eq } from 'drizzle-orm';
import { db } from './db/client.js';
import { funds, portcos } from './db/schema.js';
import { createDocumentsModule } from './modules/documents/index.js';
import { createDocumentsRoutes } from './modules/documents/http.js';

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const isUuid = (value: string) => uuidPattern.test(value);
const documentsModule = createDocumentsModule({ db });
const documentsRoutes = createDocumentsRoutes(documentsModule);

export const app = new Hono()
  .use(
    '*',
    cors({
      origin: 'http://localhost:3000',
    }),
  )
  .get('/health', (c) => c.json({ status: 'ok' }))
  .get('/funds', async (c) => {
    const rows = await db
      .select({ id: funds.id, name: funds.name, slug: funds.slug })
      .from(funds)
      .orderBy(asc(funds.name), asc(funds.id));

    return c.json({ data: rows });
  })
  .get('/funds/:fundId/portcos', async (c) => {
    const fundId = c.req.param('fundId');
    if (!isUuid(fundId)) {
      return c.json({ error: 'Invalid fund id' }, 400);
    }

    const [fund] = await db.select({ id: funds.id }).from(funds).where(eq(funds.id, fundId));
    if (!fund) {
      return c.json({ error: 'Fund not found' }, 404);
    }

    const rows = await db
      .select({
        id: portcos.id,
        fundId: portcos.fundId,
        code: portcos.code,
        name: portcos.name,
        slug: portcos.slug,
      })
      .from(portcos)
      .where(eq(portcos.fundId, fundId))
      .orderBy(asc(portcos.code), asc(portcos.id));

    return c.json({ data: rows });
  })
  .route('/', documentsRoutes)
  .get('/dump', (c) =>
    c.json({
      message: 'Frontend-to-backend RPC is working.',
      service: 'second-brain-api',
      checkedAt: new Date().toISOString(),
    }),
  )
  .notFound((c) => c.json({ error: 'Not found' }, 404))
  .onError((error, c) => {
    console.error(error);
    return c.json({ error: 'Internal server error' }, 500);
  });

export type AppType = typeof app;
}

@media (max-width: 720px) {
  .fund-index {
    padding: 56px 0;
  }
  .app-shell {
    display: block;
  }
  .scope-rail {
    border-bottom: 1px solid var(--color-rule);
    border-right: 0;
    padding: 24px;
  }
  .scope-nav {
    display: flex;
    gap: 16px;
    margin-top: 24px;
    overflow-x: auto;
  }
  .scope-nav a {
    padding: 4px 0;
    white-space: nowrap;
  }
  .scope-caption {
    display: none;
  }
  .reading-pane {
    padding: 48px 24px;
  }
  .fund-row {
    align-items: start;
    flex-direction: column;
    gap: 10px;
  }
  .fund-row > :last-child {
    text-align: left;
  }
  .detail-list > div {
    display: block;
  }
  .detail-list dd {
    margin-top: 6px;
  }
}

@media (prefers-reduced-motion: no-preference) {
  a {
    transition: color 140ms ease;
  }
}
