export const Route = createFileRoute('/')({ component: Home })

function Home() {
  const funds = useQuery({ queryKey: ['funds'], queryFn: fetchFunds })

  return (
    <main className="fund-index">
      <header className="index-heading">
        <p className="wordmark">Second Brain</p>
        <h1>Workspaces</h1>
        <p>Choose a fund.</p>
      </header>
      {funds.isPending ? <p className="query-state">Loading funds…</p> : null}
      {funds.isError ? <p className="query-state query-error">{funds.error.message}</p> : null}
      {funds.data ? (
        <table className="list-table">
          <caption>Available funds</caption>
          <thead>
            <tr>
              <th>Fund</th>
              <th>Workspace</th>
            </tr>
          </thead>
          <tbody>
            {funds.data.data.map((fund) => (
              <tr key={fund.id}>
                <td>{fund.name}</td>
                <td>
                  <Link to="/$type/$slug" params={{ type: 'fund', slug: fund.slug }}>
                    Open fund
                  </Link>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : null}
    </main>
  )
}
