    border-right: 0;
    padding: 24px;
  }
  .scope-nav {
    display: flex;
    gap: 16px;
    margin-top: 24px;
    overflow-x: auto;
  }
  .scope-nav a {
    padding: 4px 0;
    white-space: nowrap;
  }
  .scope-caption {
    display: none;
  }
  .reading-pane {
    padding: 48px 24px;
  }
  .fund-row {
    align-items: start;
    flex-direction: column;
    gap: 10px;
  }
