.locked-scope {
  border-left: 2px solid var(--color-accent);
  color: var(--color-muted);
  font-size: 0.84rem;
  line-height: 1.5;
  margin: 0;
  padding-left: 10px;
}
.document-dropzone {
  align-items: center;
  border: 1px dashed var(--color-muted);
  color: var(--color-muted);
  cursor: pointer;
  display: grid;
  justify-items: center;
  min-height: 154px;
  padding: 20px;
  text-align: center;
}
.document-dropzone:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}
.document-dropzone input {
  block-size: 1px;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  inline-size: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
}
.document-dropzone strong {
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 400;
}
.document-dropzone span {
  font-size: 0.78rem;
}
.import-error {
  color: var(--color-failure);
  font-size: 0.84rem;
  margin: -4px 0 0;
}
.import-actions {
  display: flex;
  justify-content: end;
}

@media (max-width: 720px) {
  .fund-index {
    padding: 56px 0;
