import { useQuery } from '@tanstack/react-query'
import { Link, createFileRoute, notFound } from '@tanstack/react-router'
import { fetchPortcos } from '../../../../lib/fund-queries'
import { Route as ScopeRoute } from '../route'

export const Route = createFileRoute('/$type/$slug/portcos/')({ component: PortcoList })

function PortcoList() {
  const { type } = Route.useParams()
  const { fund, portco } = ScopeRoute.useLoaderData()
  const portcos = useQuery({
    queryKey: ['funds', fund?.id, 'portcos'],
    queryFn: () => fetchPortcos(fund!.id),
    enabled: Boolean(fund),
  })

  if (type !== 'fund' || portco) throw notFound()
  if (portcos.isPending) return <ListState>Loading portfolio companies…</ListState>
  if (portcos.isError) return <ListState error>{portcos.error.message}</ListState>

  return (
    <main className="fund-index">
      <header className="index-heading">
        <p className="breadcrumb">
          <Link to="/$type/$slug" params={{ type: 'fund', slug: fund.slug }}>
            {fund.name}
          </Link>
        </p>
        <h1>Portfolio companies</h1>
        <p>Choose a company to work within its scoped record.</p>
      </header>
      <table className="list-table">
        <caption>{fund.name} portfolio companies</caption>
        <thead>
          <tr>
            <th>Code</th>
            <th>Company</th>
            <th>Workspace</th>
          </tr>
        </thead>
        <tbody>
          {portcos.data.data.map((portco) => (
            <tr key={portco.id}>
              <td>{portco.code}</td>
              <td>{portco.name}</td>
              <td>
                <Link to="/$type/$slug" params={{ type: 'portco', slug: portco.slug }}>
                  Open company
                </Link>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

function ListState({ children, error = false }: { children: React.ReactNode; error?: boolean }) {
  return (
    <main className="fund-index">
      <p className={`query-state${error ? ' query-error' : ''}`}>{children}</p>
    </main>
  )
}
import { useQuery } from '@tanstack/react-query'
import { fetchPortcos } from '../lib/fund-queries'

export type Scope = {
  fundId: string
  portcoId?: string | null
  portcoSlug?: string
}

type ScopeSelectProps = {
  fundId: string
  portcoId?: string | null
  onScopeChange: (scope: Scope) => void
  disabled?: boolean
}

/**
 * A controlled selector for the two document scopes available within a fund:
 * the whole fund or one of its portfolio companies.
 */
export function ScopeSelect({
  fundId,
  portcoId,
  onScopeChange,
  disabled = false,
}: ScopeSelectProps) {
  const portcos = useQuery({
    queryKey: ['funds', fundId, 'portcos'],
    queryFn: () => fetchPortcos(fundId),
  })

  return (
    <label className="scope-select">
      <span>Scope</span>
      <select
        value={portcoId ?? ''}
        disabled={disabled || portcos.isPending}
        onChange={(event) => {
          const selected = portcos.data?.data.find((portco) => portco.id === event.target.value)
          onScopeChange({
            fundId,
            portcoId: selected?.id,
            portcoSlug: selected?.slug,
          })
        }}
      >
        <option value="">Fund-wide</option>
        {portcos.data?.data.map((portco) => (
          <option key={portco.id} value={portco.id}>
            {portco.code} — {portco.name}
          </option>
        ))}
      </select>
      {portcos.isError ? <small>Portfolio companies could not be loaded.</small> : null}
    </label>
  )
}
