import { Link, Outlet, createFileRoute, notFound, useNavigate } from '@tanstack/react-router'
import { ScopeSelect } from '../../../components/scope-select'
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarInset,
  SidebarProvider,
  SidebarSeparator,
  SidebarTrigger,
} from '../../../components/ui/sidebar'
import { fetchScope, ScopeQueryError, type ScopeType } from '../../../lib/scope-queries'

export const Route = createFileRoute('/$type/$slug')({
  loader: async ({ params }) => {
    if (params.type !== 'fund' && params.type !== 'portco') throw notFound()
    try {
      const response = await fetchScope(params.type as ScopeType, params.slug)
      if (!response.data) throw notFound()
      return response.data
    } catch (error) {
      if (error instanceof ScopeQueryError && error.status === 404) throw notFound()
      throw error
    }
  },
  component: ScopedLayout,
})

function ScopedLayout() {
  const { type, slug } = Route.useParams()
  const { fund, portco } = Route.useLoaderData()
  const navigate = useNavigate()

  return (
    <SidebarProvider>
      <Sidebar collapsible="offcanvas" className="second-brain-sidebar">
        <SidebarHeader className="sidebar-brand">
          <Link to="/" className="sidebar-wordmark">
            Second Brain
          </Link>
          <p>Evidence for better decisions.</p>
        </SidebarHeader>
        <SidebarSeparator />
        <SidebarContent>
          <div className="sidebar-scope">
            <ScopeSelect
              fundId={fund.id}
              portcoId={portco?.id}
              onScopeChange={(nextScope) => {
                void navigate({
                  to: '/$type/$slug',
                  params: {
                    type: nextScope.portcoSlug ? 'portco' : 'fund',
                    slug: nextScope.portcoSlug ?? fund.slug,
                  },
                })
              }}
            />
          </div>
          <nav aria-label="Workspace navigation" className="sidebar-navigation">
            <Link to="/$type/$slug" params={{ type, slug }} activeOptions={{ exact: true }}>
              Overview
            </Link>
            <Link to="/$type/$slug/portcos" params={{ type: 'fund', slug: fund.slug }}>
              Portfolio companies
            </Link>
          </nav>
        </SidebarContent>
      </Sidebar>
      <SidebarInset className="reading-pane">
        <header className="mobile-shell-header">
          <SidebarTrigger aria-label="Open workspace navigation" />
          <span>{portco?.name ?? fund.name}</span>
        </header>
        <Outlet />
      </SidebarInset>
    </SidebarProvider>
  )
}
import { useQuery } from '@tanstack/react-query'
import { Link, createFileRoute } from '@tanstack/react-router'
import { DocumentImport, DocumentList } from '../../../modules/documents'
import { fetchPortcos } from '../../../lib/fund-queries'
import { Route as ScopeRoute } from './route'

export const Route = createFileRoute('/$type/$slug/')({ component: ScopedOverview })

function ScopedOverview() {
  const { fund, portco } = ScopeRoute.useLoaderData()
  const documentsScope = { fundId: fund.id, portcoId: portco?.id }

  return (
    <main className="workspace-content">
      <header className="page-heading">
        <p className="breadcrumb">
          <Link to="/$type/$slug" params={{ type: 'fund', slug: fund.slug }}>
            {fund.name}
          </Link>
          {portco ? ` / ${portco.code}` : ''}
        </p>
        <h1>{portco?.name ?? fund.name}</h1>
        <p>{portco ? 'Portfolio company scope' : 'Fund-wide scope'}</p>
      </header>
      {!portco ? <PortfolioTable fundId={fund.id} fundSlug={fund.slug} /> : null}
      <section className="data-section documents-section" aria-labelledby="documents-heading">
        <div className="section-heading">
          <div>
            <h2 id="documents-heading">Documents</h2>
            <p>Source material available to this view.</p>
          </div>
          <DocumentImport scope={documentsScope} />
        </div>
        <DocumentList scope={documentsScope} />
      </section>
    </main>
  )
}

function PortfolioTable({ fundId, fundSlug }: { fundId: string; fundSlug: string }) {
  const portcos = useQuery({
    queryKey: ['funds', fundId, 'portcos'],
    queryFn: () => fetchPortcos(fundId),
  })
  if (portcos.isPending) return <p className="query-state">Loading portfolio companies…</p>
  if (portcos.isError) return <p className="query-state query-error">{portcos.error.message}</p>
  return (
    <section className="data-section" aria-labelledby="portfolio-heading">
      <div className="section-heading">
        <h2 id="portfolio-heading">Portfolio</h2>
        <Link to="/$type/$slug/portcos" params={{ type: 'fund', slug: fundSlug }}>
          View all companies
        </Link>
      </div>
      <div className="company-list">
        {portcos.data.data.map((company) => (
          <Link
            key={company.id}
            to="/$type/$slug"
            params={{ type: 'portco', slug: company.slug }}
            className="company-row"
          >
            <span className="company-code">{company.code}</span>
            <span>
              <strong>{company.name}</strong>
            </span>
            <span className="company-open">Open company</span>
          </Link>
        ))}
      </div>
    </section>
  )
}
import { useQuery } from '@tanstack/react-query'
import { Link, createFileRoute, notFound } from '@tanstack/react-router'
import { fetchPortcos } from '../../../../lib/fund-queries'
import { Route as ScopeRoute } from '../route'

export const Route = createFileRoute('/$type/$slug/portcos/')({ component: PortcoList })

function PortcoList() {
  const { type } = Route.useParams()
  const { fund, portco } = ScopeRoute.useLoaderData()
  const portcos = useQuery({
    queryKey: ['funds', fund?.id, 'portcos'],
    queryFn: () => fetchPortcos(fund!.id),
    enabled: Boolean(fund),
  })

  if (type !== 'fund' || portco) throw notFound()
  if (portcos.isPending) return <ListState>Loading portfolio companies…</ListState>
  if (portcos.isError) return <ListState error>{portcos.error.message}</ListState>

  return (
    <main className="fund-index">
      <header className="index-heading">
        <p className="breadcrumb">
          <Link to="/$type/$slug" params={{ type: 'fund', slug: fund.slug }}>
            {fund.name}
          </Link>
        </p>
        <h1>Portfolio companies</h1>
        <p>Choose a company to work within its scoped record.</p>
      </header>
      <table className="list-table">
        <caption>{fund.name} portfolio companies</caption>
        <thead>
          <tr>
            <th>Code</th>
            <th>Company</th>
            <th>Workspace</th>
          </tr>
        </thead>
        <tbody>
          {portcos.data.data.map((portco) => (
            <tr key={portco.id}>
              <td>{portco.code}</td>
              <td>{portco.name}</td>
              <td>
                <Link to="/$type/$slug" params={{ type: 'portco', slug: portco.slug }}>
                  Open company
                </Link>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

function ListState({ children, error = false }: { children: React.ReactNode; error?: boolean }) {
  return (
    <main className="fund-index">
      <p className={`query-state${error ? ' query-error' : ''}`}>{children}</p>
    </main>
  )
}
import { useQuery } from '@tanstack/react-query'
import { fetchPortcos } from '../lib/fund-queries'

export type Scope = {
  fundId: string
  portcoId?: string | null
  portcoSlug?: string
}

type ScopeSelectProps = {
  fundId: string
  portcoId?: string | null
  onScopeChange: (scope: Scope) => void
  disabled?: boolean
}

/**
 * A controlled selector for the two document scopes available within a fund:
 * the whole fund or one of its portfolio companies.
 */
export function ScopeSelect({
  fundId,
  portcoId,
  onScopeChange,
  disabled = false,
}: ScopeSelectProps) {
  const portcos = useQuery({
    queryKey: ['funds', fundId, 'portcos'],
    queryFn: () => fetchPortcos(fundId),
  })

  return (
    <label className="scope-select">
      <span>Scope</span>
      <select
        value={portcoId ?? ''}
        disabled={disabled || portcos.isPending}
        onChange={(event) => {
          const selected = portcos.data?.data.find((portco) => portco.id === event.target.value)
          onScopeChange({
            fundId,
            portcoId: selected?.id,
            portcoSlug: selected?.slug,
          })
        }}
      >
        <option value="">Fund-wide</option>
        {portcos.data?.data.map((portco) => (
          <option key={portco.id} value={portco.id}>
            {portco.code} — {portco.name}
          </option>
        ))}
      </select>
      {portcos.isError ? <small>Portfolio companies could not be loaded.</small> : null}
    </label>
  )
}
