.document-dropzone {
  align-items: center;
  border: 1px dashed var(--color-muted);
  color: var(--color-muted);
  cursor: pointer;
  display: grid;
  justify-items: center;
  min-height: 154px;
  padding: 20px;
  text-align: center;
}
.document-dropzone:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}
.document-dropzone input {
  block-size: 1px;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  inline-size: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
}
.document-dropzone strong {
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 400;
}
.document-dropzone span {
  font-size: 0.78rem;
}
.import-error {
  color: var(--color-failure);
  font-size: 0.84rem;
  margin: -4px 0 0;
}
.import-actions {
  display: flex;
  justify-content: end;
}

@media (max-width: 720px) {
  .fund-index {
    padding: 56px 0;
  }
  .app-shell {
    display: block;
  }
  .scope-rail {
    border-bottom: 1px solid var(--color-rule);
    border-right: 0;
    padding: 24px;
  }
  .scope-nav {
    display: flex;
    gap: 16px;
    margin-top: 24px;
    overflow-x: auto;
  }
  .scope-nav a {
    padding: 4px 0;
    white-space: nowrap;
  }
  .scope-caption {
    display: none;
  }
  .reading-pane {
    max-width: none;
    padding: 48px 24px;
  }
  .workspace-content {
    width: 100%;
    padding: 24px 0 56px;
  }
  .mobile-shell-header {
    align-items: center;
    display: flex;
    gap: 10px;
    min-height: 40px;
  }
  .mobile-shell-header > span {
    color: var(--color-muted);
    font-size: 0.84rem;
  }
  .fund-row {
    align-items: start;
    flex-direction: column;
    gap: 10px;
  }
  .fund-row > :last-child {
    text-align: left;
  }
  .detail-list > div {
    display: block;
  }
  .detail-list dd {
    margin-top: 6px;
  }
  .section-heading {
    align-items: start;
    gap: 16px;
  }
}

@media (prefers-reduced-motion: no-preference) {
  a {
    transition: color 140ms ease;
  }
}

:root {
  --sidebar: var(--color-paper);
  --sidebar-foreground: var(--color-ink);
  --sidebar-primary: var(--color-accent);
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f1eee6;
  --sidebar-accent-foreground: var(--color-ink);
  --sidebar-border: var(--color-rule);
  --sidebar-ring: var(--color-accent);
}

@theme inline {
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

