@import 'tailwindcss';

@custom-variant dark (&:is(.dark *));

@theme {
  --color-paper: #faf8f3;
  --color-card: #ffffff;
  --color-rule: #e3e0d8;
  --color-ink: #1d2129;
  --color-muted: #6b7280;
  --color-accent: #2f6f4f;
  --color-attention: #b7791f;
  --color-failure: #b3402f;
  --font-serif: Georgia, 'Times New Roman', serif;
  --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
}

@layer base {
  * {
    box-sizing: border-box;
  }

  body {
    margin: 0;
    background: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
  }

  a {
    color: inherit;
  }

  :focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }
}

.fund-index {
  width: min(760px, calc(100% - 40px));
  margin: 0 auto;
  padding: 96px 0;
}
.index-heading {
  max-width: 620px;
}
.wordmark {
  color: var(--color-accent);
  font-size: 0.9rem;
  font-weight: 650;
  text-decoration: none;
}
.index-heading h1,
.page-heading h1 {
  margin: 18px 0 12px;
  font-family: var(--font-serif);
  font-size: clamp(2.7rem, 7vw, 4.8rem);
  font-weight: 400;
  letter-spacing: -0.055em;
  line-height: 0.98;
}
.index-heading > p:last-child,
.page-heading > p:last-child {
  color: var(--color-muted);
  font-size: 1.05rem;
  line-height: 1.65;
}
.fund-list {
  margin-top: 64px;
  border-top: 1px solid var(--color-rule);
}
.query-state {
  border-top: 1px solid var(--color-rule);
  color: var(--color-muted);
  margin: 64px 0 0;
  padding: 20px 0;
}
.query-error {
  color: var(--color-failure);
}
.list-table {
  border-collapse: collapse;
  margin-top: 64px;
  text-align: left;
  width: 100%;
}
.list-table caption {
  color: var(--color-muted);
  font-size: 0.85rem;
  margin-top: 5px;
  color: var(--color-muted);
  font-size: 0.86rem;
}
.fund-row > :last-child {
  color: var(--color-muted);
  font-size: 0.85rem;
  text-align: right;
}

.workspace-content {
  width: min(940px, calc(100% - 40px));
  margin: 0 auto;
  padding: 48px 0 80px;
}
.sidebar-wordmark {
  color: var(--color-accent);
  font-family: var(--font-serif);
  font-size: 1.3rem;
  text-decoration: none;
}
.workspace-inset {
  min-width: 0;
  background: var(--color-paper);
}
.sidebar-scope {
  padding: 18px 20px 8px;
}
.sidebar-scope .scope-select > span {
  color: var(--color-muted);
  font-size: 0.72rem;
  font-weight: 600;
}
.sidebar-scope .scope-select select {
  width: 100%;
}
.sidebar-footer {
  border-top: 1px solid var(--color-rule);
}
.mobile-shell-header {
  display: none;
}
.breadcrumb {
  color: var(--color-muted);
  font-size: 0.83rem;
  margin: 0;
}
.breadcrumb a {
  text-decoration-color: var(--color-rule);
  text-underline-offset: 3px;
}
.agenda {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 24px;
  border-top: 1px solid var(--color-ink);
  border-bottom: 1px solid var(--color-rule);
  margin-top: 56px;
  padding: 22px 0;
}
.agenda h2,
.section-heading h2 {
  font-size: 0.9rem;
  font-weight: 650;
  margin: 0;
}
.section-heading p {
  color: var(--color-muted);
  font-size: 0.82rem;
  line-height: 1.45;
  margin: 5px 0 0;
}
.agenda p:not(.status) {
  color: var(--color-muted);
  font-size: 0.92rem;
  line-height: 1.5;
  margin: 7px 0 0;
}
.status {
  color: var(--color-muted);
  font-size: 0.82rem;
  margin: 0;
  white-space: nowrap;
}
.status-needs-attention {
  color: var(--color-failure) !important;
}
.status-on-pace {
  color: var(--color-attention) !important;
}
.status-on-plan {
  color: var(--color-accent) !important;
}
.data-section {
  margin-top: 46px;
}
.section-heading {
  align-items: baseline;
  display: flex;
  justify-content: space-between;
  padding-bottom: 14px;
}
.section-heading a {
  color: var(--color-muted);
  font-size: 0.82rem;
  text-decoration-color: var(--color-rule);
  text-underline-offset: 3px;
}
.company-list {
  border-top: 1px solid var(--color-rule);
}
.company-row {
  align-items: center;
  display: grid;
  gap: 16px;
  grid-template-columns: 48px 1fr auto;
  border-bottom: 1px solid var(--color-rule);
  padding: 18px 0;
  text-decoration: none;
}
.company-code {
  color: var(--color-muted);
  font-size: 0.8rem;
}
.detail-list {
  border-top: 1px solid var(--color-rule);
  margin: 0;
}
.detail-list > div {
  display: grid;
}
.import-error {
  color: var(--color-failure);
  font-size: 0.84rem;
  margin: -4px 0 0;
}
.import-actions {
  display: flex;
  justify-content: end;
}

@media (max-width: 720px) {
  .fund-index {
    padding: 56px 0;
  }
  .workspace-inset {
    max-width: none;
  }
  .workspace-content {
    width: 100%;
    padding: 24px 0 56px;
  }
  .mobile-shell-header {
    align-items: center;
    border-bottom: 1px solid var(--color-rule);
    display: flex;
    gap: 10px;
    min-height: 40px;
    margin: 0 -24px;
    padding: 10px 24px;
  }
  .mobile-shell-header > span {
    color: var(--color-muted);
    font-size: 0.84rem;
  }
  .fund-row {
    align-items: start;
    flex-direction: column;
    gap: 10px;
  }
  .fund-row > :last-child {
    text-align: left;
  }
  .detail-list > div {
    display: block;
  }
  .detail-list dd {
    margin-top: 6px;
  }
  .section-heading {
    align-items: start;
    gap: 16px;
  }
}

@media (prefers-reduced-motion: no-preference) {
  a {
    transition: color 140ms ease;
  }
}

