import { Link, Outlet, createFileRoute, notFound, useNavigate } from '@tanstack/react-router'
import type { CSSProperties } from 'react'
import { ScopeSelect } from '../../../components/scope-select'
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarFooter,
  SidebarInset,
  SidebarProvider,
  SidebarSeparator,
  SidebarTrigger,
} from '../../../components/ui/sidebar'
import { fetchScope, ScopeQueryError, type ScopeType } from '../../../lib/scope-queries'

export const Route = createFileRoute('/$type/$slug')({
  loader: async ({ params }) => {
    if (params.type !== 'fund' && params.type !== 'portco') throw notFound()
    try {
      const response = await fetchScope(params.type as ScopeType, params.slug)
      if (!response.data) throw notFound()
      return response.data
    } catch (error) {
      if (error instanceof ScopeQueryError && error.status === 404) throw notFound()
      throw error
    }
  },
  component: ScopedLayout,
})

function ScopedLayout() {
  const { fund, portco } = Route.useLoaderData()
  const navigate = useNavigate()

  return (
    <SidebarProvider style={{ '--sidebar-width': '17rem' } as CSSProperties}>
      <Sidebar collapsible="offcanvas" className="second-brain-sidebar">
        <SidebarHeader className="sidebar-scope">
          <ScopeSelect
            fundId={fund.id}
            portcoId={portco?.id}
            onScopeChange={(nextScope) => {
              void navigate({
                to: '/$type/$slug',
                params: {
                  type: nextScope.portcoSlug ? 'portco' : 'fund',
                  slug: nextScope.portcoSlug ?? fund.slug,
                },
              })
            }}
          />
        </SidebarHeader>
        <SidebarSeparator />
        <SidebarContent />
        <SidebarFooter className="sidebar-footer">
          <Link to="/" className="sidebar-wordmark">
            Second Brain
          </Link>
        </SidebarFooter>
      </Sidebar>
      <SidebarInset className="workspace-inset">
        <header className="mobile-shell-header">
          <SidebarTrigger aria-label="Open workspace navigation" />
          <span>{portco?.name ?? fund.name}</span>
        </header>
        <Outlet />
      </SidebarInset>
    </SidebarProvider>
  )
}
import { useQuery } from '@tanstack/react-query'
import { fetchPortcos } from '../lib/fund-queries'

export type ScopeSelection = {
  portcoId?: string
  portcoSlug?: string
}

type ScopeSelectProps = {
  fundId: string
  portcoId?: string | null
  onScopeChange: (scope: ScopeSelection) => void
  disabled?: boolean
}

/**
 * A controlled selector for the two document scopes available within a fund:
 * the whole fund or one of its portfolio companies.
 */
export function ScopeSelect({
  fundId,
  portcoId,
  onScopeChange,
  disabled = false,
}: ScopeSelectProps) {
  const portcos = useQuery({
    queryKey: ['funds', fundId, 'portcos'],
    queryFn: () => fetchPortcos(fundId),
  })

  return (
    <label className="scope-select">
      <span>Scope</span>
      <select
        value={portcoId ?? ''}
        disabled={disabled || portcos.isPending}
        onChange={(event) => {
          const selected = portcos.data?.data.find((portco) => portco.id === event.target.value)
          onScopeChange({
            portcoId: selected?.id,
            portcoSlug: selected?.slug,
          })
        }}
      >
        <option value="">Fund-wide</option>
        {portcos.data?.data.map((portco) => (
          <option key={portco.id} value={portco.id}>
            {portco.code} — {portco.name}
          </option>
        ))}
      </select>
      {portcos.isError ? <small>Portfolio companies could not be loaded.</small> : null}
    </label>
  )
}
import { useState, type DragEvent } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { ScopeSelect, type ScopeSelection } from '../../components/scope-select'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '../../components/ui/dialog'
import { api } from '../../lib/api'

export type DocumentScope = {
  fundId: string
  portcoId?: string | null
}

type DocumentListProps = {
  scope: DocumentScope
}

type DocumentImportProps = {
  scope: DocumentScope
}

const documentQueryKey = (scope: DocumentScope) => [
  'documents',
  scope.fundId,
  scope.portcoId ?? null,
]

async function fetchDocuments(scope: DocumentScope) {
  const response = await api.documents.$get({
    query: {
      fundId: scope.fundId,
      ...(scope.portcoId ? { portcoId: scope.portcoId } : {}),
    },
  })

  if (!response.ok) {
    throw new Error(`Could not load documents (status ${response.status}).`)
  }

  return response.json()
}

/** Lists the documents in a fund-wide or portfolio-company scope. */
export function DocumentList({ scope }: DocumentListProps) {
  const documents = useQuery({
    queryKey: documentQueryKey(scope),
    queryFn: () => fetchDocuments(scope),
  })

  if (documents.isPending) return <p className="query-state">Loading documents…</p>
  if (documents.isError) return <p className="query-state query-error">{documents.error.message}</p>

  if (documents.data.data.length === 0) {
    return <p className="empty-documents">No documents have been imported into this scope.</p>
  }

  return (
    <div className="document-table-wrap">
      <table className="document-table">
        <thead>
          <tr>
            <th scope="col">Document</th>
            <th scope="col">Scope</th>
            <th scope="col">Imported</th>
            <th scope="col">Status</th>
          </tr>
        </thead>
        <tbody>
          {documents.data.data.map((document) => (
            <tr key={document.id}>
              <td>
                <strong>{document.title}</strong>
                <small>{document.filename}</small>
              </td>
              <td>{document.portcoId ? 'Portfolio company' : 'Fund-wide'}</td>
              <td>
                {new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' }).format(
                  new Date(document.createdAt)
                )}
              </td>
              <td>
                <span className={`document-status document-status-${document.status}`}>
                  {document.status}
                </span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

/** Imports a text or Markdown document, keeping the selected scope explicit. */
export function DocumentImport({ scope }: DocumentImportProps) {
  const queryClient = useQueryClient()
  const [open, setOpen] = useState(false)
  const [file, setFile] = useState<File | null>(null)
  const [title, setTitle] = useState('')
  const [targetScope, setTargetScope] = useState<DocumentScope>(scope)

  const importDocument = useMutation({
    mutationFn: async () => {
      if (!file) throw new Error('Choose a document before importing.')

      const response = await api.documents.$post({
        form: {
          file,
          fundId: targetScope.fundId,
          ...(targetScope.portcoId ? { portcoId: targetScope.portcoId } : {}),
          ...(title.trim() ? { title: title.trim() } : {}),
        },
      })

      if (!response.ok) {
        const body = await response.json().catch(() => null)
        const message =
          body && 'error' in body ? body.error : `Import failed (status ${response.status}).`
        throw new Error(message)
      }
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ['documents', scope.fundId] })
      setFile(null)
      setTitle('')
      setTargetScope(scope)
      setOpen(false)
    },
  })

  function chooseFile(candidate: File | undefined) {
    if (!candidate) return
    setFile(candidate)
    importDocument.reset()
  }

  function handleDrop(event: DragEvent<HTMLLabelElement>) {
    event.preventDefault()
    chooseFile(event.dataTransfer.files[0])
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <button type="button" className="import-button">
          Import document
        </button>
      </DialogTrigger>
      <DialogContent className="document-dialog">
        <DialogHeader>
          <DialogTitle>Import a document</DialogTitle>
          <DialogDescription>
            Add Markdown or plain text to the evidence available in this scope.
          </DialogDescription>
        </DialogHeader>
        <form
          className="document-import-form"
          onSubmit={(event) => {
            event.preventDefault()
            importDocument.mutate()
          }}
        >
          {scope.portcoId ? (
            <p className="locked-scope">This import stays within the current portfolio company.</p>
          ) : (
            <ScopeSelect
              fundId={scope.fundId}
              portcoId={targetScope.portcoId}
              onScopeChange={(selection: ScopeSelection) =>
                setTargetScope({ fundId: scope.fundId, portcoId: selection.portcoId })
              }
              disabled={importDocument.isPending}
            />
          )}
          <label className="document-title">
            <span>
              Title <em>optional</em>
            </span>
            <input
              value={title}
              onChange={(event) => setTitle(event.target.value)}
              placeholder={file?.name ?? 'Use the filename'}
              disabled={importDocument.isPending}
            />
          </label>
          <label
            className="document-dropzone"
            htmlFor="document-file"
            onDragOver={(event) => event.preventDefault()}
            onDrop={handleDrop}
          >
            <input
              id="document-file"
              type="file"
              accept=".md,.markdown,.txt,text/markdown,text/plain"
              onChange={(event) => chooseFile(event.target.files?.[0])}
              disabled={importDocument.isPending}
            />
            <strong>{file ? file.name : 'Drop a document here'}</strong>
            <span>
              {file
                ? `${Math.ceil(file.size / 1024)} KB · choose another file`
                : 'or choose a file · Markdown or text · up to 5 MB'}
            </span>
          </label>
