@import 'tailwindcss';

@custom-variant dark (&:is(.dark *));

@theme {
  --color-paper: #faf8f3;
  --color-card: #ffffff;
  --color-rule: #e3e0d8;
  --color-ink: #1d2129;
  --color-muted: #6b7280;
  --color-accent: #2f6f4f;
  --color-attention: #b7791f;
