@import 'tailwindcss';

@custom-variant dark (&:is(.dark *));

@theme {
  --color-paper: #faf8f3;
  --color-card: #ffffff;
  --color-rule: #e3e0d8;
  --color-ink: #1d2129;
  --color-muted: #6b7280;
  --color-accent: #2f6f4f;
  --color-attention: #b7791f;
  --color-failure: #b3402f;
  --font-serif: Georgia, 'Times New Roman', serif;
  --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
}

@layer base {
  * {
    box-sizing: border-box;
  }

  body {
    margin: 0;
    background: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
  }

  a {
    color: inherit;
  }

  :focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }
}

.fund-index {
  width: min(760px, calc(100% - 40px));
  margin: 0 auto;
  padding: 96px 0;
}
.index-heading {
  max-width: 620px;
}
.wordmark {
  color: var(--color-accent);
  font-size: 0.9rem;
  font-weight: 650;
  text-decoration: none;
}
.index-heading h1,
.page-heading h1 {
  margin: 18px 0 12px;
  font-family: var(--font-serif);
  font-size: clamp(2.7rem, 7vw, 4.8rem);
  font-weight: 400;
  letter-spacing: -0.055em;
  line-height: 0.98;
}
.index-heading > p:last-child,
.page-heading > p:last-child {
  color: var(--color-muted);
  font-size: 1.05rem;
  line-height: 1.65;
}
.fund-list {
  margin-top: 64px;
  border-top: 1px solid var(--color-rule);
}
.query-state {
  border-top: 1px solid var(--color-rule);
  color: var(--color-muted);
  margin: 64px 0 0;
  padding: 20px 0;
}
.query-error {
  color: var(--color-failure);
}
.list-table {
  border-collapse: collapse;
  margin-top: 64px;
  text-align: left;
  width: 100%;
}
.list-table caption {
  color: var(--color-muted);
  font-size: 0.85rem;
  margin-bottom: 12px;
  text-align: left;
}
.list-table th {
  border-bottom: 1px solid var(--color-ink);
  color: var(--color-muted);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 10px 12px 10px 0;
}
.list-table td {
  border-bottom: 1px solid var(--color-rule);
  padding: 18px 12px 18px 0;
}
.list-table td:last-child,
.list-table th:last-child {
  padding-right: 0;
}
.list-table a {
  color: var(--color-accent);
  font-size: 0.9rem;
  text-decoration-color: color-mix(in srgb, var(--color-accent), transparent 65%);
  text-underline-offset: 3px;
}
.fund-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid var(--color-rule);
  padding: 24px 0;
  text-decoration: none;
}
.fund-row:hover strong,
.company-row:hover strong,
.section-heading a:hover {
  color: var(--color-accent);
}
.fund-row strong,
.company-row strong {
  display: block;
  font-family: var(--font-serif);
  font-size: 1.4rem;
  font-weight: 400;
  letter-spacing: -0.02em;
}
.fund-row small,
.company-row small {
  display: block;
  margin-top: 5px;
  color: var(--color-muted);
  font-size: 0.86rem;
}
.fund-row > :last-child {
  color: var(--color-muted);
  font-size: 0.85rem;
  text-align: right;
}

.workspace-content {
  width: min(940px, calc(100% - 40px));
  margin: 0 auto;
  padding: 48px 0 80px;
}
.sidebar-wordmark {
  color: var(--color-accent);
  font-family: var(--font-serif);
  font-size: 1.3rem;
  text-decoration: none;
}
.workspace-inset {
  min-width: 0;
  background: var(--color-paper);
}
.sidebar-scope {
  padding: 18px 20px 8px;
}
.sidebar-scope .scope-select > span {
  color: var(--color-muted);
  font-size: 0.72rem;
  font-weight: 600;
}
.sidebar-scope .scope-select select {
  width: 100%;
}
.sidebar-footer {
  border-top: 1px solid var(--color-rule);
}
.mobile-shell-header {
  display: none;
}
.breadcrumb {
  color: var(--color-muted);
  font-size: 0.83rem;
  margin: 0;
}
.breadcrumb a {
  text-decoration-color: var(--color-rule);
  text-underline-offset: 3px;
}
.agenda {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 24px;
  border-top: 1px solid var(--color-ink);
  border-bottom: 1px solid var(--color-rule);
  margin-top: 56px;
  padding: 22px 0;
}
.agenda h2,
.section-heading h2 {
  font-size: 0.9rem;
  font-weight: 650;
  margin: 0;
}
.section-heading p {
  color: var(--color-muted);
  font-size: 0.82rem;
  line-height: 1.45;
  margin: 5px 0 0;
}
.agenda p:not(.status) {
  color: var(--color-muted);
  font-size: 0.92rem;
  line-height: 1.5;
  margin: 7px 0 0;
}
.status {
  color: var(--color-muted);
  font-size: 0.82rem;
  margin: 0;
  white-space: nowrap;
}
.status-needs-attention {
  color: var(--color-failure) !important;
}
.status-on-pace {
  color: var(--color-attention) !important;
}
.status-on-plan {
  color: var(--color-accent) !important;
}
.data-section {
  margin-top: 46px;
}
.section-heading {
  align-items: baseline;
  display: flex;
  justify-content: space-between;
  padding-bottom: 14px;
}
.section-heading a {
  color: var(--color-muted);
  font-size: 0.82rem;
  text-decoration-color: var(--color-rule);
  text-underline-offset: 3px;
}
.company-list {
  border-top: 1px solid var(--color-rule);
}
.company-row {
  align-items: center;
  display: grid;
  gap: 16px;
  grid-template-columns: 48px 1fr auto;
  border-bottom: 1px solid var(--color-rule);
  padding: 18px 0;
  text-decoration: none;
}
.company-code {
  color: var(--color-muted);
  font-size: 0.8rem;
}
.detail-list {
  border-top: 1px solid var(--color-rule);
  margin: 0;
}
.detail-list > div {
  display: grid;
  grid-template-columns: 170px 1fr;
  gap: 20px;
  border-bottom: 1px solid var(--color-rule);
  padding: 18px 0;
}
.detail-list dt {
  color: var(--color-muted);
  font-size: 0.82rem;
}
.detail-list dd {
  margin: 0;
  line-height: 1.5;
}
.documents-section {
  margin-bottom: 40px;
}
.empty-documents {
  border-top: 1px solid var(--color-rule);
  color: var(--color-muted);
  font-size: 0.92rem;
  margin: 0;
  padding: 20px 0;
}
.document-table-wrap {
  border-top: 1px solid var(--color-rule);
  overflow-x: auto;
}
.document-table {
  border-collapse: collapse;
  min-width: 620px;
  text-align: left;
  width: 100%;
}
.document-table th {
  border-bottom: 1px solid var(--color-rule);
  color: var(--color-muted);
  font-size: 0.73rem;
  font-weight: 650;
  letter-spacing: 0.03em;
  padding: 12px 16px 12px 0;
  text-transform: uppercase;
}
.document-table td {
  border-bottom: 1px solid var(--color-rule);
  color: var(--color-muted);
  font-size: 0.84rem;
  padding: 16px 16px 16px 0;
}
.document-table th:last-child,
.document-table td:last-child {
  padding-right: 0;
}
.document-table strong,
.document-table small {
  display: block;
}
.document-table strong {
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 1.05rem;
  font-weight: 400;
}
.document-table small {
  margin-top: 3px;
}
.document-status {
  color: var(--color-muted);
  font-size: 0.76rem;
  text-transform: capitalize;
}
.document-status-completed {
  color: var(--color-accent);
}
.document-status-failed {
  color: var(--color-failure);
}
.import-button {
  border: 1px solid var(--color-accent);
  background: var(--color-accent);
  color: white;
  cursor: pointer;
  font: inherit;
  font-size: 0.84rem;
  padding: 9px 12px;
}
.import-button:disabled {
  cursor: wait;
  opacity: 0.55;
}
.document-dialog {
  border-color: var(--color-rule) !important;
  border-radius: 0 !important;
  background: var(--color-paper) !important;
  color: var(--color-ink);
  max-width: 570px !important;
}
.document-dialog [data-slot='dialog-title'] {
  font-family: var(--font-serif);
  font-size: 1.7rem;
  font-weight: 400;
  letter-spacing: -0.03em;
}
.document-dialog [data-slot='dialog-description'] {
  color: var(--color-muted);
  line-height: 1.5;
}
.document-import-form {
  display: grid;
  gap: 20px;
}
.scope-select,
.document-title {
  display: grid;
  gap: 7px;
}
.scope-select > span,
.document-title > span {
  font-size: 0.82rem;
  font-weight: 650;
}
.scope-select select,
.document-title input {
  border: 1px solid var(--color-rule);
  border-radius: 0;
  background: var(--color-card);
  color: var(--color-ink);
  font: inherit;
  padding: 10px 11px;
}
.scope-select small {
  color: var(--color-failure);
  font-size: 0.78rem;
}
.document-title em {
  color: var(--color-muted);
  font-size: 0.75rem;
  font-style: normal;
  font-weight: 400;
}
.locked-scope {
  border-left: 2px solid var(--color-accent);
  color: var(--color-muted);
  font-size: 0.84rem;
  line-height: 1.5;
  margin: 0;
  padding-left: 10px;
}
.document-dropzone {
  align-items: center;
  border: 1px dashed var(--color-muted);
  color: var(--color-muted);
  cursor: pointer;
  display: grid;
  justify-items: center;
  min-height: 154px;
  padding: 20px;
  text-align: center;
}
.document-dropzone:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}
.document-dropzone input {
  block-size: 1px;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  inline-size: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
}
.document-dropzone strong {
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 400;
}
.document-dropzone span {
  font-size: 0.78rem;
}
.import-error {
  color: var(--color-failure);
  font-size: 0.84rem;
  margin: -4px 0 0;
}
.import-actions {
  display: flex;
  justify-content: end;
}

@media (max-width: 720px) {
  .fund-index {
    padding: 56px 0;
  }
  .workspace-inset {
    max-width: none;
  }
  .workspace-content {
    width: 100%;
    padding: 24px 20px 56px;
  }
  .mobile-shell-header {
    align-items: center;
    border-bottom: 1px solid var(--color-rule);
    display: flex;
