  }
  .fund-row > :last-child {
    text-align: left;
  }
  .detail-list > div {
    display: block;
  }
  .detail-list dd {
    margin-top: 6px;
  }
  .section-heading {
    align-items: start;
    gap: 16px;
  }
}

@media (prefers-reduced-motion: no-preference) {
  a {
    transition: color 140ms ease;
  }
}

