import { api } from './api'

export type ChatScope = { fundId: string; portcoId?: string | null }

const scopeQuery = (scope: ChatScope) => ({
  fundId: scope.fundId,
  ...(scope.portcoId ? { portcoId: scope.portcoId } : {}),
})

export async function createChat(scope: ChatScope, initialMessage: string) {
  const response = await api.chats.$post({
    json: { ...scope, initialMessage, portcoId: scope.portcoId ?? null },
  })
  if (!response.ok) throw new Error(`Could not start chat (status ${response.status}).`)
  return response.json()
}

export async function fetchChat(scope: ChatScope, chatId: string) {
  const response = await api.chats[':chatId'].$get({ param: { chatId }, query: scopeQuery(scope) })
  if (!response.ok) throw new Error(`Could not load chat (status ${response.status}).`)
  return response.json()
}
import { useQuery } from '@tanstack/react-query'
import { Link, createFileRoute, notFound } from '@tanstack/react-router'
import { fetchChat, type ChatScope } from '../../../../../lib/chat-queries'
import { Route as ScopeRoute } from '../../route'

export const Route = createFileRoute('/$type/$slug/chat/$chatId/')({ component: ChatPage })

function ChatPage() {
  const { type, slug, chatId } = Route.useParams()
  const { fund, portco } = ScopeRoute.useLoaderData()
  const scope: ChatScope = { fundId: fund.id, portcoId: portco?.id }
  const chat = useQuery({
    queryKey: ['chat', chatId, scope.fundId, scope.portcoId ?? null],
    queryFn: () => fetchChat(scope, chatId),
  })

  if (chat.isPending) return <ChatState>Loading conversation…</ChatState>
  if (chat.isError) {
    if (chat.error.message.includes('(status 404)')) throw notFound()
    return <ChatState error>{chat.error.message}</ChatState>
  }
  const conversation = chat.data.data

  return (
    <main className="mx-auto flex min-h-full w-[min(800px,calc(100%-40px))] flex-col py-12 max-[720px]:w-full max-[720px]:px-5 max-[720px]:py-6">
      <header className="border-b border-rule pb-6">
        <p className="m-0 text-[0.83rem] text-muted">
          <Link
            className="underline decoration-rule underline-offset-[3px]"
            to="/$type/$slug"
            params={{ type, slug }}
          >
            {portco?.name ?? fund.name}
          </Link>
        </p>
        <h1 className="my-4 font-serif text-3xl font-normal tracking-[-0.03em]">
          {conversation.title ?? 'Conversation'}
        </h1>
        <p className="m-0 text-[0.82rem] text-muted">
          {portco ? 'Portfolio company scope' : 'Fund-wide scope'}
        </p>
      </header>
      <ol className="m-0 grid list-none gap-7 p-0 py-8">
        {conversation.messages.map((message) => (
          <li
            key={message.id}
            className="max-w-[720px] border-l-2 pl-4"
            style={{
              borderColor:
                message.role === 'assistant' ? 'var(--color-accent)' : 'var(--color-rule)',
            }}
          >
            <p className="m-0 mb-2 text-[0.76rem] font-semibold capitalize text-muted">
              {message.role}
            </p>
            <p className="m-0 whitespace-pre-wrap text-[0.96rem] leading-[1.7] text-ink">
              {message.content}
            </p>
          </li>
        ))}
      </ol>
      <form
        className="mt-auto border-t border-rule pt-5"
        onSubmit={(event) => event.preventDefault()}
      >
        <label className="grid gap-2" htmlFor="follow-up-message">
          <span className="text-[0.9rem] font-semibold">Continue this conversation</span>
          <textarea
            id="follow-up-message"
            rows={3}
            disabled
            placeholder="Follow-up questions will be available soon."
            className="w-full resize-y rounded-none border border-rule bg-card p-3 font-inherit text-ink disabled:cursor-not-allowed disabled:bg-muted"
          />
        </label>
        <p className="mt-2 text-[0.78rem] text-muted">Follow-up responses are not available yet.</p>
      </form>
    </main>
  )
}

function ChatState({ children, error = false }: { children: React.ReactNode; error?: boolean }) {
  return (
    <main className="mx-auto w-[min(800px,calc(100%-40px))] py-12 text-muted max-[720px]:w-full max-[720px]:px-5 max-[720px]:py-6">
      <p className={error ? 'text-failure' : undefined}>{children}</p>
    </main>
  )
}

